('cpc157', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الموجات والضوء', 'معامل انكسار وسط شفاف n يُعرّف بالنسبة بين سرعة الضوء في الفراغ c وسرعته v في هذا الوسط بالعلاقة:', '["n = c / v","n = v / c","n = c × v","n = c² / v"]'::jsonb, 'n = c / v', 'معامل الانكسار المطلق لوسط شفاف هو n = c/v وهو دائماً أكبر من أو يساوي 1.'),
('cpc158', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الموجات والضوء', 'ظاهرة تبدد الضوء الأبيض (Dispersion) بواسطة موشور ترجع إلى كون:', '["معامل انكسار الزجاج يتغير بتغير طول موجة الإشعاع الأحادي اللون المار عبره","الزجاج يمتص كل الألوان ما عدا البنفسجي","الضوء الأبيض يفقد طاقته عند دخول الموشور","سرعة الضوء ثابتة تماماً في جميع الأوساط"]'::jsonb, 'معامل انكسار الزجاج يتغير بتغير طول موجة الإشعاع الأحادي اللون المار عبره', 'الوسط المبدد هو وسط تتعلق فيه سرعة انتشار الموجة الضوئية بترددها، ومنه اختلاف زاوية الانحراف للألوان.'),
('cpc159', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'التحولات النووية', 'ما هو التفتت بيتا ناقص (β⁻) من منظور التفاعل النووي الدقيق داخل النواة؟', '["تحول نيوترون إلى بروتون مع انبعاث إلكترون وضديد نيوترينو","تحول بروتون إلى نيوترون مع انبعاث بوزيترون","انشطار النواة إلى نواتين خفيفتين","التقاط إلكتروني من مدارات الذرة"]'::jsonb, 'تحول نيوترون إلى بروتون مع انبعاث إلكترون وضديد نيوترينو', 'في التفتت β⁻: يتحول نيوترون n(0,1) إلى بروتون p(1,1) وإلكترون e(-1,0) وضديد نيوترينو.'),
('cpc160', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'التحولات النووية', 'طاقة الربط لنواة (Énergie de liaison) تعبر عن:', '["الطاقة الواجب منحها للنواة في حالة سكون لفصل نوياتها مع بقائها ساكنة","طاقة الحركة التي تتحرك بها النواة في الفراغ","الطاقة المنبعثة عند تكوين الذرة من إلكتروناتها","طاقة التجاذب الكهرسكوني بين الإلكترونات"]'::jsonb, 'الطاقة الواجب منحها للنواة في حالة سكون لفصل نوياتها مع بقائها ساكنة', 'طاقة الربط E_l = Δm × c² حيث Δm هو النقص الكتلي للنواة (كتلة النويات منفصلة ناقص كتلة النواة).'),
('cpc161', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'التحولات النووية', 'تكون نواة أكثر استقراراً كلما كانت:', '["طاقة الربط بالنسبة للنوية (E_l / A) أكبر","كتلتها الإجمالية أكبر من 200 وحدة كتلة ذرية","عدد بروتوناتها مساوياً لصفر","عمر نصفها أصغر من ميكرو ثانية"]'::jsonb, 'طاقة الربط بالنسبة للنوية (E_l / A) أكبر', 'معيار استقرار النوى هو طاقة الربط لكل نوية E_l/A (تبلغ أقصاها حوالي 8.8 MeV للحديد 56).'),
('cpc162', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء والتوازن الكيميائي', 'تفاعل كيميائي تكون نسبة تقدمه النهائي τ = x_f / x_max = 1 هو تفاعل:', '["كلي وتام","محدود وغير تام ويصل لحالة توازن","مستحيل الحدوث تلقائياً","بطيء جداً ويتوقف في البداية"]'::jsonb, 'كلي وتام', 'إذا كانت τ = 1 فإن التقدم النهائي يطابق التقدم الأقصى، مما يعني استهلاك المتفاعل المحد كلياً (تفاعل تام).'),
('cpc163', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء وثابتة التوازن', 'ثابتة التوازن K المقرونة بمعادلة تفاعل كيميائي في حالة توازن تتعلق فقط بـ:', '["درجة الحرارة","التراكيز البدئية للمتفاعلات","حجم الإناء الذي يحتوي الخليط","الضغط الجوي دائماً"]'::jsonb, 'درجة الحرارة', 'ثابتة التوازن K تميز التفاعل الكيميائي وتتعلق حصرياً بدرجة الحرارة ولا ترتبط بالتركيب البدئي للمجموعة.'),
('cpc164', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء ومعيار التطور التلقائي', 'إذا كان خارج التفاعل في الحالة البدئية Qr,i أصغر من ثابتة التوازن K (Qr,i < K)، فإن المجموعة الكيميائية تتطور:', '["تلقائياً في المنحى المباشر (1) لإنتاج النواتج","تلقائياً في المنحى غير المباشر (2) المعاكس","تكون في حالة توازن ديناميكي ولا تتطور","تتطور في المنحيين معاً بنفس السرعة فوراً"]'::jsonb, 'تلقائياً في المنحى المباشر (1) لإنتاج النواتج', 'حسب معيار التطور التلقائي: عندما يكون Qr < K تتطور المجموعة نحو اليمين لزيادة النواتج حتى يصل Qr = K.'),
('cpc165', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء وتفاعلات الأسترة والحلمأة', 'تفاعل الأسترة بين حمض كربوكسيلي وكحول أولي يتميز بكونه:', '["بطيئاً ومحدوداً ولاتحرياً (Athermique) ومردوده يقارب 67%","سريعاً جداً وانفجارياً","تاماً وكلياً ويستهلك كل الحمض دائماً","ناشراً لحرارة هائلة"]'::jsonb, 'بطيئاً ومحدوداً ولاتحرياً (Athermique) ومردوده يقارب 67%', 'تفاعل الأسترة-حلمأة تفاعل عكوس محدود بطيء وغير ناشر أو ماص للحرارة، مردوده 67% مع كحول أولي متساوي المولات.'),
('cpc166', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء والحفز', 'ما هو دور «الحفاز» (Catalyseur) في تفاعل كيميائي؟', '["يزيد من سرعة الوصول إلى حالة التوازن دون أن يغير من تركيب خليط التوازن ولا يظهر في المعادلة الحصيلة","يزيد من كمية الناتج النهائي الأقصى","يغير من قيمة ثابتة التوازن K للتفاعل","يبطئ التفاعلات السريعة لتفادي الانفجار"]'::jsonb, 'يزيد من سرعة الوصول إلى حالة التوازن دون أن يغير من تركيب خليط التوازن ولا يظهر في المعادلة الحصيلة', 'الحفاز يخفض طاقة التنشيط فيسرع التفاعل دون المساس بالحالة النهائية للتوازن أو الثابتة K.'),
('cpc167', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكهرباء والأعمدة الكهروكيميائية', 'في عمود دانييل (Pile Daniell)، ما هو التفاعل الذي يحدث عند القطب السالب (الأنود)؟', '["أكسدة فلز الخارصين: Zn → Zn²⁺ + 2e⁻","اختزال أيونات النحاس: Cu²⁺ + 2e⁻ → Cu","أكسدة النحاس إلى أيونات النحاس","تفكك حمض الكبريتيك إلى غاز الهيدروجين"]'::jsonb, 'أكسدة فلز الخارصين: Zn → Zn²⁺ + 2e⁻', 'الأنود هو القطب السالب في العمود الكهروكيميائي ويحدث عنده دائماً تفاعل الأكسدة (فقدان الإلكترونات).'),
('cpc168', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكهرباء والأعمدة الكهروكيميائية', 'ما هو الدور الأساسي للقنطرة الأيونية (Pont salin) في العمود الكهروكيميائي؟', '["ضمان الحياد الكهربائي للمحلولين في نصفي العمود وإغلاق الدارة الكهربائية","توليد الطاقة الكهربائية مباشرة من الأملاح","منع انتقال الإلكترونات في السلك الخارجي","تبريد العمود أثناء الاشتغال"]'::jsonb, 'ضمان الحياد الكهربائي للمحلولين في نصفي العمود وإغلاق الدارة الكهربائية', 'القنطرة الأيونية تسمح بهجرة الأنيونات والكاتيونات للحفاظ على التعادل الكهربائي في الكأسين واستمرار مرور التيار.'),
('cpc169', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك وحركة قذيفة', 'في حركة قذيفة في مجال الثقالة المنتظم وبإهمال الهواء، ما شكل مسار القذيفة عندما تكون زاوية القذف α محصورة بين 0 و 90 درجة؟', '["شلجمي (Parabolique) في المستوى الرأسي لحركة القذيفة","دائري نصف قطره المسافة الأفقية","مستقيمي عمودي على سطح الأرض","جيبي يتذبذب صعوداً وهبوطاً"]'::jsonb, 'شلجمي (Parabolique) في المستوى الرأسي لحركة القذيفة', 'معادلة المسار تكتب على شكل y = -g/(2 v0² cos²α) x² + tanα x، وهي معادلة شلجم تقع قمته في الأعلى.'),
('cpc170', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك وحركة قذيفة', 'للحصول على أقصى مدى أفقي ممكن لقذيفة بنفس السرعة البدئية v0، ما هي زاوية القذف المثلى؟', '["45 درجة","30 درجة","60 درجة","90 درجة"]'::jsonb, '45 درجة', 'المدى يتناسب مع sin(2α)، ويبلغ أقصاه عندما يكون 2α = 90° أي α = 45°.'),
('cpc171', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك ودوران جسم صلب', 'عزم القوة M_Δ(F) بالنسبة لمحور دوران ثابت Δ يُعرّف بـ:', '["الجداء الجبري للشدة F في المسافة العمودية d الفاصلة بين خط تأثير القوة والمحور","حاصل قسمة F على d","مربع الشدة في المسافة d","الكتلة في تسارع الدوران"]'::jsonb, 'الجداء الجبري للشدة F في المسافة العمودية d الفاصلة بين خط تأثير القوة والمحور', 'عزم القوة: M_Δ(F) = ± F × d ويقاس بالنيوتن متر (N.m).'),
('cpc172', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك ودوران جسم صلب', 'العلاقة الأساسية للتحريك في حالة الدوران حول محور ثابت Δ تنص على أن مجموع عزوم القوى الخارجية يساوي:', '["J_Δ × θ'''' (جداء عزم القصور في التسارع الزاوي)","J_Δ × θ'' (جداء عزم القصور في السرعة الزاوية)","m × a_G","نصف عزم القصور في مربع السرعة الزاوية"]'::jsonb, 'J_Δ × θ'''' (جداء عزم القصور في التسارع الزاوي)', 'العلاقة الأساسية للتحريك في الدوران: ∑ M_Δ(F_ext) = J_Δ × θ''''.'),
('cpc173', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكهرباء والتحريض الكهرومغناطيسي', 'قانون فاراداي (Faraday) ينص على أن القوة الكهرحركية التحريضية e المتولدة في دارة تساوي:', '["e = - dΦ / dt (المشتقة الزمنية لتدفق المجال المغناطيسي مسبوقة بإشارة ناقص)","e = dΦ / dt","e = Φ × t","e = B × I × L"]'::jsonb, 'e = - dΦ / dt (المشتقة الزمنية لتدفق المجال المغناطيسي مسبوقة بإشارة ناقص)', 'قانون فاراداي-لينز: e = -dΦ/dt، حيث تعبر إشارة الناقص عن قانون لينز (التيار التحريضي يعاكس السبب الذي أحدثه).'),
('cpc174', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكهرباء والتضمين', 'ما هي المراحل الثلاث الأساسية لدارة كشف الغلاف (Détection d''enveloppe) لإزالة تضمين الوسع؟', '["تقويم ثنائي القطب (الصمام)، ثم مرشح ممرر للترددات المنخفضة RC، ثم مكثف لحذف المركبة المستمرة","مضخم صوتي، ومحول جهد، وبطارية","موشور عاكس، وشق ضوئي، وعدسة مجمعة","مكثف هوائي، ومقاومة حرارية، وجرس كهربائي"]'::jsonb, 'تقويم ثنائي القطب (الصمام)، ثم مرشح ممرر للترددات المنخفضة RC، ثم مكثف لحذف المركبة المستمرة', 'كشف الغلاف يتطلب حذف النوبات السالبة بصمام ثنائي، ثم ترشيح التردد الحامل بدارة RC، ثم حذف المركبة المستمرة بمكثف.'),
('cpc175', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الموجات والموجات فوق الصوتية', 'الموجات فوق الصوتية هي موجات ميكانيكية طولية ترددها:', '["أكبر من 20 كيلوهرتز (f > 20 kHz) وغير مسموعة للأذن البشرية","محصور بين 20 هرتز و 20 كيلوهرتز","أقل من 20 هرتز","كهرومغناطيسية تنتشر في الفراغ بسرعة الضوء"]'::jsonb, 'أكبر من 20 كيلوهرتز (f > 20 kHz) وغير مسموعة للأذن البشرية', 'المجال فوق الصوتي يتجاوز عتبة السمع البشري (20 kHz) وتتطلب وسطاً مادياً للانتشار بتضاغط وتمدد طولي.'),
('cpc176', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء والموصلية والمواصلة', 'قانون كولروش (Kohlrausch) يعبر عن الموصلية σ لمحلول إلكتروليتي ممدد بالعلاقة:', '["σ = مجموع λ_i × [X_i] (مجموع جداءات الموصلية المولية الأيونية في تراكيز الأيونات)","σ = G × (S / L)","σ = [X_i] / λ_i","σ = R × I"]'::jsonb, 'σ = مجموع λ_i × [X_i] (مجموع جداءات الموصلية المولية الأيونية في تراكيز الأيونات)', 'قانون كولروش: σ = ∑ λ_i [X_i]، ويعتمد على إسهام كل أيون في نقل التيار الكهربائي.'),
('cpc177', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء والمعايرة المباشرة', 'عند نقطة التكافؤ (Équivalence) في معايرة حمض-قاعدة، ما الخاصية التي تتحقق دائماً؟', '["تختفي المتفاعلات المعايِرة والمعايَرة بنسب المعاملات الستوكيومترية تماماً","يصبح pH المحلول مساوياً لـ 7 دائماً","يتغير لون المحلول إلى الأسود القاتم","ينفد الماء الموجود في البيشر كلياً"]'::jsonb, 'تختفي المتفاعلات المعايِرة والمعايَرة بنسب المعاملات الستوكيومترية تماماً', 'التكافؤ هو الحالة التي تختفي فيها كميات مادة المتفاعلين معاً: n_A/a = n_B/b (الخليط ستوكيومتري).'),
('cpc178', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء والكواشف الملونة', 'يكون الكاشف الملون ملائماً لمعايرة حمض-قاعدة إذا كانت:', '["منطقة انعطافه تحتوي على قيمة الـ pH عند التكافؤ","منطقة انعطافه تساوي الصفر دائماً","لونه يتغير فقط عند درجة غليان الماء","كتلته المولية أكبر من 500 g/mol"]'::jsonb, 'منطقة انعطافه تحتوي على قيمة الـ pH عند التكافؤ', 'معيار اختيار الكاشف الملون هو أن يقع pH التكافؤ (pH_E) داخل منطقة انعطاف الكاشف (Zone de virage).'),
('cpc179', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء والتحليل الكهربائي', 'التحليل الكهربائي (Électrolyse) هو تحول كيميائي:', '["قسري غير تلقائي يتم بفعل تيار كهربائي يفرضه مولد خارجي","تلقائي يولد طاقة كهربائية ومستمر تلقائياً","يحدث فقط في الغازات النبيلة","لا يرافقه أي انتقال للإلكترونات"]'::jsonb, 'قسري غير تلقائي يتم بفعل تيار كهربائي يفرضه مولد خارجي', 'التحليل الكهربائي تفاعل قسري مفروض ينعكس فيه منحى التطور التلقائي بواسطة طاقة كهربائية خارجية.'),
('cpc180', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'التحولات النووية والانشطار', 'الانشطار النووي (Fission nucléaire) هو تفاعل نووي حراري يتم فيه:', '["انقسام نواة ثقيلة شطورة إلى نواتين أخف تحت قذف بنيوترون بطيء","التحام نواتين خفيفتين لتكوين نواة أثقل","تفكك تلقائي دون أي قذف خارجي","انبعاث أشعة إكس من الطبقات الإلكترونية"]'::jsonb, 'انقسام نواة ثقيلة شطورة إلى نواتين أخف تحت قذف بنيوترون بطيء', 'الانشطار هو قذف نواة ثقيلة (كاليورانيوم 235) بنيوترون حراري فتنشطر لنواتين مع تحرير طاقة هائلة ونيوترونات جديدة.'),
('cpc181', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'التحولات النووية والاندماج', 'الاندماج النووي (Fusion nucléaire) هو تفاعل يتم فيه:', '["التحام نواتين خفيفتين لتكوين نواة أكثر استقراراً مع تحرير طاقة كبيرة","انقسام نواة البلوتونيوم إلى ذرات هيدروجين","فقدان النواة لشحنتها الكهربائية كلياً","انبعاث جسيمات ألفا فقط"]'::jsonb, 'التحام نواتين خفيفتين لتكوين نواة أكثر استقراراً مع تحرير طاقة كبيرة', 'الاندماج (مثل اندماج الدوتريوم والتريتيوم لإنتاج الهيليوم) يحرر طاقة لكل نوية أكبر من طاقة الانشطار ويحدث في قلب النجوم.'),
('cpc182', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك والسرعة والتسارع', 'في أساس فريني (Repère de Frenet) لحركة منحنية، مركبة التسارع المماسي a_t تساوي:', '["a_t = dv / dt (المشتقة الزمنية للسرعة البديهية)","a_t = v² / ρ","a_t = 0 دائماً","a_t = g cos(θ)"]'::jsonb, 'a_t = dv / dt (المشتقة الزمنية للسرعة البديهية)', 'في معلم فريني: التسارع الكلي a = a_t u + a_n n، حيث a_t = dv/dt و a_n = v²/ρ (التسارع المنظمي).'),
('cpc183', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك والسرعة والتسارع', 'في حركة دائرية منتظمة، كيف يكون شعاع التسارع؟', '["انجذابي مركزي (Centripète) موجه نحو مركز الدائرة ومنظمي فقط (a = v² / R)","مماسي للمسار في نفس منحى السرعة","منعدم لأن السرعة البديهية ثابتة","موجه نحو خارج الدائرة بشكل طارد"]'::jsonb, 'انجذابي مركزي (Centripète) موجه نحو مركز الدائرة ومنظمي فقط (a = v² / R)', 'في الحركة الدائرية المنتظمة، dv/dt = 0 فتختفي المركبة المماسية، ويبقى التسارع المنظمي فقط موجهاً نحو المركز.'),
('cpc184', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكهرباء والطاقة في الوشيعة', 'ما هي الطاقة المغناطيسية E_m المخزونة في وشيعة معامل تحريضها L يمر بها تيار شدته I ؟', '["E_m = (1/2) L I²","E_m = L I","E_m = (1/2) L² I","E_m = L I²"]'::jsonb, 'E_m = (1/2) L I²', 'الطاقة المغناطيسية للوشيعة تعطى بالعلاقة الكلاسيكية: E_m = (1/2) L I².'),
('cpc185', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك والاحتكاك المائع', 'أثناء سقوط كرة في سائل لزج بقوة احتكاك مائع f = -k v، ما الخاصية التي تميز السرعة الحدية v_lim ؟', '["تصبح السرعة ثابتة وينعدم تسارع حركة الكرة (a = 0)","تتزايد السرعة إلى ما لا نهاية","تنعدم السرعة وتتوقف الكرة فوراً في السائل","تتذبذب السرعة صعوداً وهبوطاً"]'::jsonb, 'تصبح السرعة ثابتة وينعدم تسارع حركة الكرة (a = 0)', 'عند الوصول للسرعة الحدية، تتعادل قوة الثقالة مع مجموع دافعة أرخميدس والاحتكاك فيصبح التسارع a = 0 وتستقر السرعة.'),
('cpc186', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء وزمن نصف التفاعل', 'زمن نصف التفاعل t_{1/2} لتفاعل كيميائي هو المدة الزمنية اللازمة لـ:', '["بلوغ تقدم التفاعل نصف قيمته النهائية (x = x_f / 2)","انتهاء التفاعل كلياً واختفاء المتفاعلات","تضاعف درجة حرارة خليط التفاعل","استهلاك نصف كتلة المذيب المستخدم"]'::jsonb, 'بلوغ تقدم التفاعل نصف قيمته النهائية (x = x_f / 2)', 'حسب التعريف الحركي: t_{1/2} هي اللحظة التي يصل فيها تقدم التفاعل نصف تقدمه النهائي.'),
('cpc187', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء وحمض كربوكسيلي ومشتقاته', 'للحصول على مردود تام وسريع لتفاعل الأسترة دون تكون الماء، يُستحسن استبدال الحمض الكربوكسيلي بـ:', '["أندريد الحمض (Anhydride d''acide) أو كلورور الأسيل","كحول ثانوي آخر","ألكان خطي","قاعدة قوية مثل هيدروكسيد الصوديوم"]'::jsonb, 'أندريد الحمض (Anhydride d''acide) أو كلورور الأسيل', 'مشتقات الأحماض الكربوكسيلية (أندريدات وكلورورات الأسيل) أكثر تفاعلية وتجعل تصنيع الإستر سريعاً وكلياً (تاماً).'),
('cpc188', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء وتصبن الإستر', 'تفاعل تصبن الإستر (Saponification) مع محلول أيونات الهيدروكسيد HO⁻ يتميز بكونه:', '["تفاعلاً بطيئاً وتاماً ينتج عنه الكحول وأيون الكربوكسيلات (الصابون)","تفاعلاً عكوساً ومحدوداً مردوده 5%","تفاعلاً ينتج عنه غاز الأكسجين النقي","تفاعلاً لا يمكن أن يحدث في المختبر"]'::jsonb, 'تفاعلاً بطيئاً وتاماً ينتج عنه الكحول وأيون الكربوكسيلات (الصابون)', 'التصبن هو الحلمأة القلوية للإستر بواسطة قاعدة قوية HO⁻، وهو تفاعل كلي وتام يصنع الصابون.'),
('cpc189', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك وكمية الحركة', 'في نظام معزول ميكانيكياً (مجموع القوى الخارجية منعدم)، ما الكمية الفيزيائية التي تنحفظ؟', '["متجهة كمية الحركة الإجمالية للنظام (p = ∑ m_i v_i = متجهة ثابتة)","الطاقة الحرارية فقط","سرعة كل جسم على حدة","حجم النظام وأبعاده الهندسية"]'::jsonb, 'متجهة كمية الحركة الإجمالية للنظام (p = ∑ m_i v_i = متجهة ثابتة)', 'مبدأ انحفاظ كمية الحركة: إذا كانت ∑ F_ext = 0 فإن dp/dt = 0 وبالتالي p = Cste.'),
('cpc190', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكهرباء وتضمين التردد', 'في التضمين الترددي (FM)، ما المعلمة الفيزيائية للإشارة الحاملة التي تتغير وفق الإشارة المضمنة؟', '["تردد الموجة الحاملة مع بقاء وسعها ثابتاً","وسع الموجة الحاملة فقط","سرعة انتشار الموجة في الهواء","طبيعة الموجة من كهرومغناطيسية إلى صوتية"]'::jsonb, 'تردد الموجة الحاملة مع بقاء وسعها ثابتاً', 'في التضمين FM، يتغير التردد اللحظي للموجة الحاملة تناسبياً مع إشارة المعلومات مع الحفاظ على وسع ثابت.'),
('cpc191', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الموجات وتأثير دوبلر', 'تأثير دوبلر (Effet Doppler) يتمثل في:', '["تغير التردد المدرك لموجة بسبب الحركة النسبية بين المنبع والملاحظ","انكسار الضوء عند عبوره وسطين شفافين","امتصاص الصوت داخل الأجسام المسامية","تغير سرعة الضوء بتغير شدة الإضاءة"]'::jsonb, 'تغير التردد المدرك لموجة بسبب الحركة النسبية بين المنبع والملاحظ', 'عند اقتراب المنبع الصوتي يزداد التردد المدرك (صوت حاد)، وعند ابتعاده ينخفض التردد (صوت غليظ).'),
('cpc192', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك وقوة لورنتز', 'القوة المغناطيسية المطبقة على شحنة q تتحرك بسرعة v في مجال مغناطيسي B تعطى بـ:', '["F = q (v ∧ B) (الجداء المتجهي للسرعة والمجال)","F = q E + B","F = m v B","F = q v / B"]'::jsonb, 'F = q (v ∧ B) (الجداء المتجهي للسرعة والمجال)', 'قوة لورنتز المغناطيسية: F_mag = q(v ∧ B)، وهي دائماً عمودية على مستوي المتجهتين v و B.'),
('cpc193', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك وحركة شحنة في مجال مغناطيسي', 'حركة دقيقة مشحونة تدخل عمودياً على مجال مغناطيسي منتظم B بسرعة v0 تكون:', '["دائرية منتظمة في مستوى عمودي على B","مستقيمية متسارعة بانتظام","شلجمية مفتوحة نحو القطب الشمالي","حلزونية بنصف قطر متزايد باستمرار"]'::jsonb, 'دائرية منتظمة في مستوى عمودي على B', 'قوة لورنتز عمودية على السرعة فلا تنجز شغلاً (الطاقة الحركية ثابتة) والتسارع انجذابي مركزي خالص.'),
('cpc194', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء والمحاليل المنظمة', 'المحلول المنظم (Solution tampon) هو محلول يتميز بكون:', '["قيمة الـ pH فيه تتغير قليلاً جداً عند إضافة كميات محدودة من حمض أو قاعدة أو عند التخفيف المعتدل","قيمة الـ pH فيه تساوي 0 دائماً","يغلي عند درجات حرارة منخفضة جداً","لا يحتوي على أي جزيئات ماء"]'::jsonb, 'قيمة الـ pH فيه تتغير قليلاً جداً عند إضافة كميات محدودة من حمض أو قاعدة أو عند التخفيف المعتدل', 'المحلول المنظم يتكون من حمض ضعيف وقاعدته المرافقة بتراكيز متقاربة، مما يقاوم تغيرات الـ pH.'),
('cpc195', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء وثابتة الحمضية pKa', 'العلاقة التي تربط الـ pH بثابتة الحمضية pKa للمزدوجة حمض/قاعدة (AH / A⁻) هي:', '["pH = pKa + log([A⁻] / [AH])","pH = pKa - log([A⁻] / [AH])","pH = pKa × log([AH] / [A⁻])","pKa = pH + log([A⁻] / [AH])"]'::jsonb, 'pH = pKa + log([A⁻] / [AH])', 'علاقة هندرسون-هاسلباخ الشهيرة: pH = pKa + log([Base]/[Acide]).'),
('cpc196', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكيمياء ومخطط الهيمنة', 'في محلول مائي، عندما يكون pH أكبر قطعا من pKa للمزدوجة حمض/قاعدة، فإن:', '["النوع القاعدي A⁻ هو المهيمن في المحلول ([A⁻] > [AH])","النوع الحمضي AH هو المهيمن","النوعان متساويان في التركيز","المحلول يتحول إلى راسب فوري"]'::jsonb, 'النوع القاعدي A⁻ هو المهيمن في المحلول ([A⁻] > [AH])', 'حسب علاقة pH = pKa + log([A⁻]/[AH]): إذا كان pH > pKa فإن log > 0 وبالتالي تركيز القاعدة أكبر من تركيز الحمض.'),
('cpc197', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'التحولات النووية ومخطط سيغري', 'في مخطط سيغري (Segrè) الممثل لـ N بدلالة Z، النوى المستقرة الخفيفة (Z < 20) تتموضع حول المنصف الأول:', '["N = Z (عدد النيوترونات يساوي عدد البروتونات)","N = 2 Z","Z = 2 N","N = 0"]'::jsonb, 'N = Z (عدد النيوترونات يساوي عدد البروتونات)', 'بالنسبة للنوى الخفيفة، يتحقق الاستقرار التام عندما يتساوى عدد النيوترونات مع عدد البروتونات (N/Z = 1).'),
('cpc198', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الميكانيك وقوة الثقالة الكونية', 'قانون التجاذب الكوني لنيوتن بين جسمين نقطيين كتلتيهما m1 و m2 تفصلهما مسافة r هو:', '["F = G × (m1 × m2) / r²","F = G × (m1 + m2) / r","F = G × (m1 × m2) / r","F = G × r² / (m1 × m2)"]'::jsonb, 'F = G × (m1 × m2) / r²', 'قوة التجاذب الثقالي الكوني تتناسب طردياً مع جداء الكتلتين وعكسياً مع مربع المسافة الفاصلة بينهما.'),
('cpc199', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الكهرباء والتذبذبات القسرية والرنين', 'في دارة RLC متوالية خاضعة لتوتر متناوب جيبي، تحدث ظاهرة الرنين الكهربائي (Résonance) عندما:', '["يساوي تردد المولد التردد الخاص للدارة النظري (N = N0) ويكون التوتر والتيار على توافق في الطور","تنعدم شدة التيار كلياً في الدارة","تصبح ممانعة الدارة لا نهائية","يصبح التوتر والتيار على تعامد في الطور"]'::jsonb, 'يساوي تردد المولد التردد الخاص للدارة النظري (N = N0) ويكون التوتر والتيار على توافق في الطور', 'عند الرنين الكهربائي: Lω = 1/(Cω)، وتصبح الممانعة دنوية Z = R، وتأخذ شدة التيار قيمتها القصوى ويكون cos φ = 1.'),
('cpc200', ARRAY['secondary_prep', 'secondary_qual'], 'sec_physics', 'الفيزياء الذرية والميكانيك الكمي', 'علاقة بلانك-أينشتاين لطاقة فوتون ضوئي تردده ν وطول موجته في الفراغ λ هي:', '["E = h × ν = (h × c) / λ","E = h / ν","E = h × λ","E = (1/2) h ν²"]'::jsonb, 'E = h × ν = (h × c) / λ', 'طاقة الفوتون تتناسب طردياً مع تردده ν بواسطة ثابتة بلانك h: E = hν = hc/λ.'),
('cpe116', ARRAY['secondary_prep'], 'sec_pe', 'الرياضات الجماعية', 'ما الخط الذي يقسم ملعب كرة القدم إلى نصفين؟', '["خط المنتصف","خط التماس","خط المرمى","خط الجزاء"]'::jsonb, 'خط المنتصف', 'خط المنتصف يقسم الملعب عرضيا.'),
('cpe117', ARRAY['secondary_prep'], 'sec_pe', 'الرياضات الجماعية', 'كم مدة الشوط الواحد في مباراة كرة القدم للكبار؟', '["45 دقيقة","30 دقيقة","60 دقيقة","40 دقيقة"]'::jsonb, '45 دقيقة', 'المباراة 90 دقيقة موزعة على شوطين.'),
('cpe118', ARRAY['secondary_prep'], 'sec_pe', 'الرياضات الجماعية', 'من أي مسافة تنفذ ضربة الجزاء في كرة القدم؟', '["11 مترا","9 أمتار","16 مترا","6 أمتار"]'::jsonb, '11 مترا', 'علامة الجزاء على بعد 11 مترا من خط المرمى.'),
('cpe119', ARRAY['secondary_prep'], 'sec_pe', 'الرياضات الجماعية', 'كم عدد الأشواط ومدة الشوط في كرة السلة وفق القانون الدولي؟', '["4 أشواط من 10 دقائق","2 شوطان من 20 دقيقة","3 أشواط من 15 دقيقة","4 أشواط من 15 دقيقة"]'::jsonb, '4 أشواط من 10 دقائق', 'قانون الاتحاد الدولي لكرة السلة.'),
('cpe120', ARRAY['secondary_prep'], 'sec_pe', 'الرياضات الجماعية', 'ما ارتفاع سلة كرة السلة عن الأرض؟', '["3,05 م","2,43 م","2,80 م","3,50 م"]'::jsonb, '3,05 م', 'ارتفاع الحلقة 3,05 م.'),
('cpe121', ARRAY['secondary_prep'], 'sec_pe', 'الرياضات الجماعية', 'كم مدة مباراة كرة اليد للكبار؟', '["شوطان من 30 دقيقة","شوطان من 45 دقيقة","أربعة أشواط من 15 دقيقة","شوطان من 20 دقيقة"]'::jsonb, 'شوطان من 30 دقيقة', 'المباراة 60 دقيقة.'),
('cpe122', ARRAY['secondary_prep'], 'sec_pe', 'السباحة', 'أي أنواع السباحة التالية هو الأسرع عادة؟', '["الزحف على البطن","السباحة على الظهر","الصدر","الفراشة"]'::jsonb, 'الزحف على البطن', 'الزحف على البطن أسرع طرق السباحة.'),
('cpe123', ARRAY['secondary_prep'], 'sec_pe', 'ألعاب القوى', 'أي مما يلي من مسابقات القفز؟', '["الوثب الطويل","رمي القرص","سباق 100 م","المشي"]'::jsonb, 'الوثب الطويل', 'الوثب الطويل مسابقة قفز.'),
('cpe124', ARRAY['secondary_prep'], 'sec_pe', 'ألعاب القوى', 'إلى أي نوع من السباقات ينتمي سباق 100 م؟', '["سباقات السرعة","سباقات التحمل","سباقات الحواجز","سباقات التتابع الطويل"]'::jsonb, 'سباقات السرعة', '100 م سباق سرعة.'),
