('cpe131', ARRAY['secondary_prep'], 'sec_pe', 'التغذية', 'ما الدور الأساسي للبروتينات للرياضي؟', '["بناء وإصلاح العضلات","تخزين الطاقة السريعة فقط","تنظيم النوم","تبريد الجسم"]'::jsonb, 'بناء وإصلاح العضلات', 'البروتينات لبنات العضلات.'),
('cpe132', ARRAY['secondary_prep'], 'sec_pe', 'التغذية', 'لماذا يجب شرب الماء أثناء المجهود الطويل؟', '["لتعويض الماء المفقود بالتعرق","لزيادة وزن الجسم","لتقليل النبض إلى الصفر","لتجنب التنفس"]'::jsonb, 'لتعويض الماء المفقود بالتعرق', 'التعرق يفقد الماء والأملاح.'),
('cpe133', ARRAY['secondary_prep'], 'sec_pe', 'الصفات البدنية', 'ما الصفة البدنية التي تعني سرعة تغيير الاتجاه وحسن التحكم في الحركة؟', '["الرشاقة","التحمل","القوة القصوى","المرونة فقط"]'::jsonb, 'الرشاقة', 'الرشاقة مزيج من السرعة والتوافق.'),
('cpe134', ARRAY['secondary_prep'], 'sec_pe', 'الصفات البدنية', 'ماذا تعني المرونة؟', '["القدرة على أداء حركات بمدى واسع","القدرة على حمل أثقال","القدرة على الجري طويلا","سرعة رد الفعل"]'::jsonb, 'القدرة على أداء حركات بمدى واسع', 'مرتبطة بمطاطية العضلات ومدى المفاصل.'),
