('cte128', ARRAY['secondary_prep'], 'sec_te', 'الرسم الصناعي', 'كيف تمثل الحواف المرئية في الرسم الصناعي؟', '["بخط متصل غليظ","بخط متقطع رفيع","بخط مقطع ونقطة","بخط متموج"]'::jsonb, 'بخط متصل غليظ', 'الحواف المرئية خط قوي متصل.'),
('cte129', ARRAY['secondary_prep'], 'sec_te', 'الرسم الصناعي', 'بأي نوع من الخطوط يمثل محور التماثل؟', '["خط مقطع ونقطة رفيع","خط متصل غليظ","خط متقطع غليظ","خط متموج"]'::jsonb, 'خط مقطع ونقطة رفيع', 'يسمى خط المحور.'),
('cte130', ARRAY['secondary_prep'], 'sec_te', 'الرسم الصناعي', 'ما الغاية من المقطع في الرسم الصناعي؟', '["إظهار الشكل الداخلي للشيء","تلوين الشيء","تصغير الشيء","إخفاء الأبعاد"]'::jsonb, 'إظهار الشكل الداخلي للشيء', 'المقطع يكشف الأجزاء الداخلية.'),
